import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type ResponseFile = {
  /**
   * A unique identifier that is used to identify and reference an instance of this resource. It is
   * generated by Global Payments which can be used to check the details of the file.
   */
  responseFileId?: string;
  /** This is a meaningful label for the file */
  name?: string;
  /** Global Payments generated time indicating when the object was created in ISO-8601 format. */
  timeCreated?: Date;
  /**
   * Indicates the date and time after which the url returned can no longer be used to upload a
   * file. If not set, the default will be 15 minutes from the time the resource was created
   */
  expirationDate?: Date;
  /** A unique signed URL that you can upload your file to. */
  url?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const responseFileSchema: Schema<ResponseFile> = s.object<ResponseFile>(
  {
    responseFileId: s.optional(s.string()),
    name: s.optional(s.string()),
    timeCreated: s.optional(s.dateTime()),
    expirationDate: s.optional(s.dateTime()),
    url: s.optional(s.string()),
    _keysMap: {
      responseFileId: "response_file_id",
      timeCreated: "time_created",
      expirationDate: "expiration_date",
    },
  },
  { additionalProperties: s.json() },
);
